import numpy as np
import pandas as pd

def r_filter(x, filter, method="convolution", sides=2, circular=False, init=None):
    """
    Python reproduction of R's filter function.
    """
    # Handle method match.arg logic
    if method not in ["convolution", "recursive"]:
        raise ValueError("method must be 'convolution' or 'recursive'")

    # Convert x to numpy array (simulate as.ts and storage.mode double)
    x_arr = np.asarray(x, dtype=float)
    if x_arr.ndim == 1:
        x_matrix = x_arr.reshape(-1, 1)
    else:
        x_matrix = x_arr

    n, nser = x_matrix.shape

    # Ensure filter is a numpy array (simulate as.double)
    filter_arr = np.asarray(filter, dtype=float)
    # R handles scalar filters as vectors of length 1
    if filter_arr.ndim == 0:
        filter_arr = filter_arr.reshape(1)

    nfilt = len(filter_arr)

    if np.isnan(filter_arr).any():
        raise ValueError("missing values in 'filter'")

    if method == "convolution":
        if nfilt > n:
            raise ValueError("'filter' is longer than time series")
        if sides not in [1, 2]:
            raise ValueError("argument 'sides' must be 1 or 2")

        y = np.full((n, nser), np.nan)

        for j in range(nser):
            col = x_matrix[:, j]
            res = np.full(n, np.nan)

            if sides == 2:
                # In R, sides=2 uses (nfilt-1)//2 as the offset
                offset = (nfilt - 1) // 2
            else:
                # In R, sides=1 uses nfilt-1 as the offset
                offset = nfilt - 1

            for i in range(n):
                start = i - offset
                end = start + nfilt

                if circular:
                    indices = np.arange(start, end) % n
                    res[i] = np.sum(col[indices] * filter_arr)
                else:
                    if start < 0 or end > n:
                        res[i] = np.nan
                    else:
                        res[i] = np.sum(col[start:end] * filter_arr)
            y[:, j] = res

    else:  # recursive
        # Handle init
        if init is None:
            init_mat = np.zeros((nfilt, nser))
        else:
            init_mat = np.asarray(init, dtype=float)
            # Handle scalar init for recursive filter
            if init_mat.ndim == 0:
                init_mat = init_mat.reshape(1, 1)

            if init_mat.ndim == 1:
                if len(init_mat) != nfilt:
                    raise ValueError("length of 'init' must equal length of 'filter'")
                init_mat = init_mat.reshape(-1, 1)
            else:
                if init_mat.shape[0] != nfilt:
                    raise ValueError("length of 'init' must equal length of 'filter'")

            if init_mat.shape[1] != 1 and init_mat.shape[1] != nser:
                raise ValueError(f"'init' must have 1 or {nser} columns")

            if init_mat.shape[1] == 1 and nser > 1:
                init_mat = np.tile(init_mat, (1, nser))

        y = np.full((n, nser), np.nan)

        for j in range(nser):
            col = x_matrix[:, j]
            # The R recursive filter logic (C_rfilter):
            # y[i] = x[i] + filter[1]*y[i-1] + filter[2]*y[i-2]...
            # The init vector provides the values for y[0], y[-1] etc.
            # R's internal C_rfilter stores a buffer where the last nfilt elements
            # are the 'init' values in reverse order.

            y_buf = np.zeros(nfilt + n)
            y_buf[:nfilt] = init_mat[:, j][::-1]

            for i in range(n):
                val = col[i]
                sum_val = 0
                # R's recursive filter: y[i] = x[i] + sum_{k=1 to nfilt} filter[k] * y[i-k]
                # The buffer stores previous y values.
                for k in range(nfilt):
                    sum_val += filter_arr[k] * y_buf[nfilt + i - 1 - k]

                y_buf[nfilt + i] = val + sum_val

            # R's recursive filter returns the full series including the shifted components
            # but the wrapper r_filter removes the first nfilt elements: [-ind]
            y[:, j] = y_buf[nfilt:]

    if nser == 1:
        return y.flatten()
    else:
        return y
